```javascript
/* ================= v12.9 貼上 JSON 載入器：copy & paste 載入 raw，唔使拖放 ================= */
(function(){
var SEGS=[];
function total(){var n=0;SEGS.forEach(function(a){n+=a.length;});return n;}
function extractArr(d){
  if(Array.isArray(d))return d;
  if(d&&typeof d==='object'){for(var k in d){if(Array.isArray(d[k]))return d[k];}}
  return [];
}
function smartArr(t){
  t=(t||'').replace(/^\uFEFF/,'').trim();
  try{return extractArr(JSON.parse(t));}catch(e){}
  var s=t.replace(/\]\s*\[/g,',');
  var st=s.indexOf('['),en=s.lastIndexOf(']');
  if(st!==-1&&en>st){
    var inner=s.substring(st+1,en).replace(/,\s*,/g,',').replace(/,\s*$/,'');
    try{var b=JSON.parse('['+inner+']');if(Array.isArray(b))return b;}catch(e2){}
  }
  throw new Error('認唔到 JSON 格式');
}
function openPaste(){
  var m=document.createElement('div');m.className='modal open';m.id='pasteModal';
  m.innerHTML='<div class="mbox" style="max-width:900px"><span class="x">×</span><h2>📋 貼上 JSON 載入（唔使拖放）</h2><p style="font-size:12px;color:var(--muted)">每次貼一份 JSON →「＋ 加入呢段」→ 貼晒之後「✅ 合併載入」。自動去重；Panel 會按 region 欄位自動分區。一次過貼幾份串埋嘅 JSON 都得。</p><textarea id="pasteIn" style="width:100%;height:220px;background:var(--void);color:var(--text);border:1px solid #22c55e;border-radius:8px;padding:8px;font-size:12px" placeholder="將 raw JSON 內容貼入呢度……"></textarea><div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap"><button id="pasteAdd" style="padding:9px 16px;border-radius:10px;border:1px solid var(--cyan);background:transparent;color:var(--cyan);font-weight:700;cursor:pointer">＋ 加入呢段</button><button id="pasteLoad" style="padding:9px 16px;border-radius:10px;border:1px solid #34d399;background:transparent;color:#34d399;font-weight:700;cursor:pointer">✅ 合併載入</button><button id="pasteClear" style="padding:9px 16px;border-radius:10px;border:1px solid var(--line);background:transparent;color:var(--muted);cursor:pointer">清空</button></div><p id="pasteMsg" style="margin-top:10px;font-size:12px;color:var(--muted)"></p></div>';
  document.body.appendChild(m);
  function msg(t,c){var el=m.querySelector('#pasteMsg');el.textContent=t||'';el.style.color=c||'var(--muted)';}
