    msg('已加入第 '+SEGS.length+' 段（'+arr.length+' 篇），待合併共 '+total()+' 篇。貼下一段，或撳「✅ 合併載入」。','#16a34a');
  };
  m.querySelector('#pasteLoad').onclick=function(){
    if(!SEGS.length)return msg('未加入任何段。','#f59e0b');
    var seen={},tseen={},out=[],dup=0;
    SEGS.forEach(function(arr){arr.forEach(function(a){
      var url=a.url||a.link||'';var tk=(a.title||'').toLowerCase().trim();
      if(url&&seen[url]){dup++;return;}
      if(tk&&tseen[tk]){dup++;return;}
      if(url)seen[url]=1;if(tk)tseen[tk]=1;
      out.push(a);
    });});
    DATA=norm(out);
    S.fname='pasted_'+out.length+'篇';
    if($('lastupd'))$('lastupd').textContent=new Date().toLocaleString('zh-HK');
    SEGS=[];
    m.remove();
    setStage(1);
    alert('✅ 已載入 '+out.length+' 篇（去重 '+dup+' 篇）。');
  };
  m.querySelector('#pasteClear').onclick=function(){SEGS=[];m.querySelector('#pasteIn').value='';msg('已清空。');};
}
function mount(){
  var dz=$('dz');
  if(!dz){setTimeout(mount,300);return;}
  if(document.getElementById('pasteBtn'))return;
  var btn=document.createElement('button');
  btn.id='pasteBtn';
  btn.textContent='📋 用 Copy & Paste 載入';
