<script>
var SEGS=[];
function $(id){return document.getElementById(id);}
function esc(s){var d=document.createElement('div');d.textContent=s||'';return d.innerHTML;}
function msg(id,t,c){var m=$(id);m.textContent=t||'';m.className='msg '+(c||'');}
function extractArr(d){
if(Array.isArray(d))return d;
if(d&&typeof d==='object'){for(var k in d){if(Array.isArray(d[k]))return d[k];}}
return [];
}
function smartParse(t){
t=(t||'').replace(/^\uFEFF/,'').trim();
try{var a=extractArr(JSON.parse(t));if(a.length)return a;}catch(e){}
var s=t.replace(/\]\s*\[/g,',');
var st=s.indexOf('['),en=s.lastIndexOf(']');
if(st!==-1&&en>st){
var inner=s.substring(st+1,en).replace(/,\s*,/g,',').replace(/,\s*$/,'');
try{var b=JSON.parse('['+inner+']');if(Array.isArray(b))return b;}catch(e2){}
}
throw new Error('認唔到 JSON 格式');
}
function total(){var n=0;SEGS.forEach(function(a){n+=a.length;});return n;}
function renderSegs(){
var tb=document.querySelector('#segT tbody');tb.innerHTML='';
SEGS.forEach(function(a,i){
var tr=document.createElement('tr');
tr.innerHTML='<td>第 '+(i+1)+' 段</td><td class="num">'+a.length+' 篇</td>';
tb.appendChild(tr);
});
$('segT').hidden=SEGS.length===0;
$('doMerge').disabled=SEGS.length===0;
}
$('addSeg').onclick=function(){
var t=$('rawIn').value;
if(!t.trim())return msg('msg1','未貼任何嘢，請先貼一份 JSON。','warn');
var arr;
try{arr=smartParse(t);}catch(e){return msg('msg1','解析失敗：'+e.message,'err');}
if(!arr.length)return msg('msg1','呢段冇任何文章。','err');
SEGS.push(arr);
$('rawIn').value='';
renderSegs();
msg('msg1','已加入第 '+SEGS.length+' 段（'+arr.length+' 篇），待合併共 '+total()+' 篇。可以貼下一段，或直接去步驟 2。','ok');
};
$('clrAll').onclick=function(){
SEGS=[];$('rawIn').value='';$('outJson').value='';renderSegs();
$('regT').hidden=true;$('outCard').hidden=true;
msg('msg1','已清空。');msg('msg2','');msg('msg3','');
};
$('doMerge').onclick=function(){
var seen={},tseen={},out=[],dup=0;
SEGS.forEach(function(arr){arr.forEach(function(a){
var url=a.url||a.link||'';
var tk=(a.title||'').toLowerCase().trim();
if(url&&seen[url]){dup++;return;}
if(tk&&tseen[tk]){dup++;return;}
if(url)seen[url]=1;
if(tk)tseen[tk]=1;
out.push(a);
});});
var rc={};out.forEach(function(a){var r=a.region||'unknown';rc[r]=(rc[r]||0)+1;});
var rb=document.querySelector('#regT tbody');rb.innerHTML='';
Object.keys(rc).sort().forEach(function(k){
var tr=document.createElement('tr');
tr.innerHTML='<td>'+esc(k)+'</td><td class="num">'+rc[k]+'</td>';
rb.appendChild(tr);
});
var tr2=document.createElement('tr');
tr2.innerHTML='<td><b>總計</b></td><td class="num"><b>'+out.length+' 篇</b></td>';
rb.appendChild(tr2);
$('regT').hidden=false;
$('outJson').value=JSON.stringify(out,null,2);
$('outCard').hidden=false;
msg('msg2','✅ 合併完成：'+out.length+' 篇（去除重複 '+dup+' 篇）。結果喺步驟 3，複製即可。','ok');
};
$('copyOut').onclick=function(){
var t=$('outJson').value;
if(!t)return msg('msg3','未有結果。','warn');
function done(){msg('msg3','✅ 已複製！可以貼去任何需要嘅地方。','ok');}
function fb(){$('outJson').focus();$('outJson').select();try{document.execCommand('copy');done();}catch(e){msg('msg3','複製失敗，請喺結果格 Cmd+A 全選再 Cmd+C。','err');}}
if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(done,fb);}else{fb();}
};
</script>
</body>
</html>
