收到。兩邊都俾你：**(A) Panel B 加新模型嘅準確位置**、**(B) 主 Panel 加同一款 dropdown（跟 Panel B 同步）**。

---

### A. Panel B（`ainews_weekly.html`）— 加新 AI Model 嘅位置

就係你貼出嗰段 `<select>`。想加新模型，直接喺 `</select>` 之前加一行 `<option>`，例如：

```html
<select id="modelInput">
<option>Grok</option><option>Gemini</option><option>Manus</option><option>Qwen</option><option>Deepseek</option><option>ChatGPT</option><option>Claude</option><option>MS Copilot</option><option>Kimi</option><option>你嘅新模型名</option>
</select>
```

（Panel B 嘅 JS 啟動時亦會自動補返 localStorage 入面已有、但 list 入面冇嘅模型，所以舊記錄唔會丟。）

---

### B. 主 Panel（`ainews_preview_panel.js`）— 加同一款 dropdown

將以下成段貼喺 `.js` **最尾**（v12.8 補丁之後）。它会：
- 喺 toolbar 顯示 🤖 AI Model dropdown，選項同 Panel B 一模一樣；
- 同 Panel B **共用同一個選擇**（同一個 localStorage `lazy_settings_v3`），邊邊揀都同步；
- 入庫時 `model` 欄自動寫入你揀咗嘅模型（唔再係 `dual-ai-v8`）；
- 以後加新模型，**只改 `AI_MODELS` 呢一行**。

```javascript
/* ================= v12.9 AI Model dropdown（跟 Panel B 同一款、同步） ================= */
(function(){
/* 🆕 加新 AI Model：淨係改呢一行（Panel B 嗰邊就加 <option>，見上面 A 段） */
var AI_MODELS=['Grok','Gemini','Manus','Qwen','Deepseek','ChatGPT','Claude','MS Copilot','Kimi'];
var LSS='lazy_settings_v3';
function readShared(){try{return JSON.parse(localStorage.getItem(LSS))||{settings:{}};}catch(e){return{settings:{}};}}
function writeShared(m){var o=readShared();o.settings=o.settings||{};o.settings.model=m;localStorage.setItem(LSS,JSON.stringify(o));}
function curModel(){return (readShared().settings||{}).model||'Grok';}
var tb=document.querySelector('.toolbar');
if(tb&&!document.getElementById('modelSel')){
  var lab=document.createElement('span');
  lab.style.cssText='display:inline-flex;gap:6px;align-items:center;color:var(--muted);font-size:12px;margin-left:8px';
  lab.textContent='🤖 AI Model:';
  var sel=document.createElement('select');sel.id='modelSel';
  sel.style.cssText='padding:6px 10px;border-radius:8px;border:1px solid var(--line);background:var(--surface);color:var(--text);font-size:12px;font-weight:700';
  var saved=curModel(),opts=AI_MODELS.slice();
  if(opts.indexOf(saved)===-1)opts.push(saved);
  sel.innerHTML=opts.map(function(m){return '<option'+(m===saved?' selected':'')+'>'+m+'</option>';}).join('');
  sel.onchange=function(){writeShared(sel.value);if(typeof status==='function')status();};
  lab.appendChild(sel);tb.appendChild(lab);
}
/* 入庫自動用揀咗嘅模型（唔郁原本 payloadOf 邏輯） */
if(typeof payloadOf==='function'){var _p=payloadOf;payloadOf=function(a){var p=_p(a);p.model=curModel();return p;};}
})();
