function rescueJSON(str){let start=str.indexOf('[');if(start!==-1)str=str.substring(start);else return str;let lastBrace=str.lastIndexOf('}');if(lastBrace!==-1)str=str.substring(0,lastBrace+1);if(!str.trim().endsWith(']'))str+=']';str=str.replace(/,\s*]/g,']');return str;}

/* 🚀 v5 新增：智能 JSON 縫合器 (Smart Merge) */
function smartMergeJSON(str){
  try { let a = JSON.parse(str); if(Array.isArray(a)) return a; } catch(e) {}
  let s = str;
  s = s.replace(/\]\s*\[/g, ',');
  s = s.replace(/\]\s*,\s*\[/g, ',');
  s = s.replace(/}\s*{/g, '},{');
  let start = s.indexOf('[');
  let end = s.lastIndexOf(']');
  if (start !== -1 && end !== -1 && end > start) {
    let inner = s.substring(start + 1, end);
    inner = inner.replace(/,\s*,/g, ',').replace(/,\s*$/, '').replace(/^\s*,/, '');
    let finalStr = '[' + inner + ']';
    try { let a = JSON.parse(finalStr); if(Array.isArray(a)) return a; } catch(e) {}
  }
  return JSON.parse(rescueJSON(str));
}

