/* 3) 再清一次其他舊殘留（防萬一） */
var oldSel=document.getElementById('modelSel');if(oldSel&&oldSel.parentNode)oldSel.parentNode.removeChild(oldSel);
var oldBanner=document.getElementById('modelBanner');if(oldBanner&&oldBanner.parentNode)oldBanner.parentNode.removeChild(oldBanner);
})();

