const ok=new Set(Object.keys(FINAL_CATS)),ids=window._classIds||classBatch().map(a=>a.raw_id);let n=0;
arr.forEach(r=>{const a=DATA.find(x=>x.raw_id===ids[(r.i||0)-1]);if(!a||!ok.has(r.final_category))return;a.final_category=r.final_category;a.event_key=(r.event_key||'').trim();a.classification_reason=(r.reason||'').trim();a.orig_title=a.raw_title||a.title||'';a.orig_summary=a.raw_summary||a.summary||'';a.decision='pending_editorial';n++;});
const notApplied=ids.map((id,idx)=>idx+1).filter(i=>{const a=DATA.find(x=>x.raw_id===ids[i-1]);return a&&(a.decision==='pending_classification'||!a.final_category);});
const leftNote=notApplied.length?('⚠️ 本批仍有 '+notApplied.length+' 篇未套用（AI 漏咗或格式錯）：#'+notApplied.slice(0,10).join(', ')+(notApplied.length>10?'…':'')+'\n'):'';
