function applyEdit(txt){txt=extractJSON(txt);let arr,rescued=false;try{arr=JSON.parse(txt);}catch(e){try{arr=JSON.parse(rescueJSON(txt));rescued=true;}catch(e2){alert('AI #2 JSON 解析失敗：'+e2.message);return false;}}
