function setStage(n){
  S.rawOpen=n<=2;
  if(n===3&&pendingClass().length){S.stage=2;S.cat='all';S.group='all';alert('⛔ AI #1 尚有 '+pendingClass().length+' 篇未分類。請在 ② 完成所有批次後才可做 AI #2。');build(true);return;}
  if(n===5&&!overall().ready){S.stage=4;S.cat='all';S.group='all';alert('⛔ 仍有待分類、待 AI #2 決定或 Review 項目。請先在 ④ Overall 總覽處理完成。');build(true);return;}
  if(n===6){if(!S.sb.to)S.sb.to=nowDate();S.stage=6;$('dz').classList.add('hidden');document.querySelectorAll('#stages button').forEach(q=>q.classList.toggle('active',+q.dataset.s===6));window._classBtn.style.display='none';window._editBtn.style.display='none';window._sbBtn.style.display='none';window._replaceBtn.style.display='none';window._replaceRange.style.display='none';fetchSB();return;}
  S.stage=n;S.cat='all';S.group='all';$('dz').classList.toggle('hidden',n!==1);if($('sbView'))$('sbView').classList.add('hidden');
  document.querySelectorAll('#stages button').forEach(q=>q.classList.toggle('active',+q.dataset.s===n));
  window._classBtn.style.display=n===2?'':'none';window._editBtn.style.display=n===3?'':'none';window._sbBtn.style.display=n===5?'':'none';window._replaceBtn.style.display=n===5?'':'none';window._replaceRange.style.display=n===5?'inline-flex':'none';
  if(n===5){$('replaceFrom').value=S.replace.from;$('replaceTo').value=S.replace.to||nowDate();}
  build(true);paintDashboard();
}

