}

function addModal(id,title,how,prompt,apply){const modal=document.createElement('div');modal.className='modal';modal.id=id;modal.innerHTML='<div class="mbox" style="max-width:900px"><span class="x">×</span><h2>'+title+'</h2><p>'+how+'</p><textarea id="'+id+'Out" style="width:100%;height:230px;background:var(--void);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px;font-size:12px"></textarea><br><button class="copy">📋 複製 Prompt</button><p style="margin-top:12px">貼回 AI 的 JSON：</p><textarea id="'+id+'In" style="width:100%;height:150px;background:var(--void);color:var(--text);border:1px solid #22c55e;border-radius:8px;padding:8px"></textarea><br><button class="apply">✅ 套用結果</button></div>';document.body.appendChild(modal);modal.querySelector('.x').onclick=()=>modal.classList.remove('open');modal.querySelector('.copy').onclick=e=>{navigator.clipboard.writeText($(id+'Out').value);e.target.textContent='✅ 已複製';};modal.querySelector('.apply').onclick=()=>{const t=$(id+'In').value;if(!t.trim())return alert('先貼入 AI 回覆');const okk=apply(t);if(okk)modal.classList.remove('open');};return()=>{$(id+'Out').value=prompt();$(id+'In').value='';modal.classList.add('open');};}

