<script>
var FILES=[];
var MERGED=null;
var dz=document.getElementById('dz'),fi=document.getElementById('fi');
dz.onclick=function(){fi.click();};
fi.onchange=function(e){addFiles(e.target.files);fi.value='';};
['dragover','drop'].forEach(function(t){window.addEventListener(t,function(e){e.preventDefault();});});
dz.addEventListener('dragover',function(){dz.classList.add('drag');});
dz.addEventListener('dragleave',function(){dz.classList.remove('drag');});
dz.addEventListener('drop',function(e){dz.classList.remove('drag');addFiles(e.dataTransfer.files);});

function extractArr(d){
  if(Array.isArray(d))return d;
  if(d&&typeof d==='object'){for(var k in d){if(Array.isArray(d[k]))return d[k];}}
  return [];
}
function addFiles(list){
  Array.prototype.forEach.call(list,function(f){
    var r=new FileReader();
    r.onload=function(e){
      try{
        var arr=extractArr(JSON.parse(e.target.result));
        FILES.push({name:f.name,arr:arr});
        renderFiles();
        msg('已載入 '+f.name+'（'+arr.length+' 篇）','ok');
      }catch(err){msg(f.name+' 解析失敗：'+err.message,'warn');}
    };
    r.readAsText(f);
  });
}
function renderFiles(){
  var tb=document.querySelector('#ftable tbody');tb.innerHTML='';
  FILES.forEach(function(f){
    var tr=document.createElement('tr');
    tr.innerHTML='<td>'+esc(f.name)+'</td><td class="num">'+f.arr.length+'</td>';
    tb.appendChild(tr);
  });
  document.getElementById('ftable').hidden=FILES.length===0;
  document.getElementById('mergeBtn').disabled=FILES.length===0;
  document.getElementById('dlBtn').disabled=true;
  MERGED=null;
}
function doMerge(){
  var seen={},tseen={},out=[],dup=0;
  FILES.forEach(function(f){f.arr.forEach(function(a){
    var url=a.url||a.link||'';
    var tk=(a.title||'').toLowerCase().trim();
    if(url&&seen[url]){dup++;return;}
    if(tk&&tseen[tk]){dup++;return;}
    if(url)seen[url]=1;
    if(tk)tseen[tk]=1;
    out.push(a);
  });});
  MERGED=out;
  var rc={};out.forEach(function(a){var r=a.region||'unknown';rc[r]=(rc[r]||0)+1;});
  var rb=document.querySelector('#rtable tbody');rb.innerHTML='';
  Object.keys(rc).sort().forEach(function(k){
    var tr=document.createElement('tr');
    tr.innerHTML='<td>'+esc(k)+'</td><td class="num">'+rc[k]+'</td>';
    rb.appendChild(tr);
  });
  var tr2=document.createElement('tr');
  tr2.innerHTML='<td><b>總計（已去重 '+dup+' 篇）</b></td><td class="num"><b>'+out.length+'</b></td>';
  rb.appendChild(tr2);
  document.getElementById('rtable').hidden=false;
  document.getElementById('dlBtn').disabled=false;
  msg('✅ 合併完成：'+out.length+' 篇（去重 '+dup+' 篇）。可以下載。','ok');
}
function doDownload(){
  if(!MERGED)return;
  var blob=new Blob([JSON.stringify(MERGED,null,2)],{type:'application/json'});
  var a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='merged_raw.json';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  setTimeout(function(){URL.revokeObjectURL(a.href);},1000);
  msg('✅ 已下載 merged_raw.json，拖入主 Panel 即可。','ok');
}
function doClear(){FILES=[];MERGED=null;renderFiles();document.getElementById('rtable').hidden=true;document.getElementById('dlBtn').disabled=true;msg('');}
function msg(t,cls){var m=document.getElementById('msg');m.textContent=t||'';m.className=cls||'';}
function esc(s){var d=document.createElement('div');d.textContent=s||'';return d.innerHTML;}
document.getElementById('mergeBtn').onclick=doMerge;
document.getElementById('dlBtn').onclick=doDownload;
document.getElementById('clearBtn').onclick=doClear;
</script>
</body>
</html>
