function finalInsertRows(scope){
const list=inRegion().filter(a=>isFinal(a)&&a.url&&safeUrl(a.url)!=='#'&&a.final_category);
const seen={},rows=[];
list.forEach(a=>{const k=a.event_key||a.url;if(seen[k])return;seen[k]=1;const row=payloadOf(a);if(scope&&(row.item_date<scope.from||row.item_date>scope.to))return;rows.push(row);});
return{list,rows};
}
async function insertRows(u,c,rows){
for(let i=0;i<rows.length;i+=200){const r=await fetch(u+'/rest/v1/ainews_items_final',{method:'POST',headers:{apikey:c.key,Authorization:'Bearer '+c.key,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(rows.slice(i,i+200))});if(!r.ok)throw new Error('HTTP '+r.status+' '+await r.text());}
}
