return{region:S.region,dbRegion:S.region==='taiwan'?'tw':S.region,from,to};
}
function replaceScopeLabel(scope){return '日期：'+scope.from+' 至 '+scope.to+' · 地區：'+(REGION_NAME[scope.region]||scope.region);}
function replaceScopeQuery(scope){return 'region=eq.'+encodeURIComponent(scope.dbRegion)+'&item_date=gte.'+encodeURIComponent(scope.from)+'&item_date=lte.'+encodeURIComponent(scope.to);}
async function countReplaceScope(u,c,scope){const r=await fetch(u+'/rest/v1/ainews_items_final?'+replaceScopeQuery(scope)+'&select=item_date',{headers:{apikey:c.key,Authorization:'Bearer '+c.key,Prefer:'count=exact',Range:'0-0'}});if(!r.ok)throw new Error('HTTP '+r.status+' '+await r.text());const n=Number((r.headers.get('content-range')||'').split('/')[1]);return Number.isFinite(n)?n:0;}
