/* AI News Preview v12 + v5 AI#2 升級版 + Batch 控制 + 智能 JSON 縫合 */
const REGION_NAME={global:'全球',china:'中國大陸',hongkong:'香港',taiwan:'臺灣'};
const SB_REGION={global:'全球',china:'中國大陸',hongkong:'香港',tw:'台灣'};
const FINAL_CATS={tools_access:'工具與可用性',price_free:'價錢與免費',real_use:'實際使用',work_sme:'工作與生意',learning_family:'學習與家庭',safety_trust:'真偽與安全',regulation_public:'規則與公共生活',tech_background:'技術背景'};
const CAT_COLOR={tools_access:'#16a085',price_free:'#e17055',real_use:'#00b894',work_sme:'#6c5ce7',learning_family:'#fd79a8',safety_trust:'#d63031',regulation_public:'#7b2cbf',tech_background:'#0984e3'};
const GROUPS={'日常可用':['tools_access','price_free','real_use'],'生活與經濟':['work_sme','learning_family'],'安全與公共':['safety_trust','regulation_public'],'技術背景':['tech_background']};
const DECISION={pending_classification:{l:'待 AI #1 分類',c:'#64748b'},pending_editorial:{l:'待 AI #2 決定',c:'#f59e0b'},accept:{l:'AI 接受',c:'#16a34a'},review:{l:'待人覆核',c:'#ea580c'},reject:{l:'AI 拒絕',c:'#dc2626'}};
let BATCH_SIZE=50;
let DATA=[],SB=[],S={region:'hongkong',cat:'all',group:'all',stage:1,fname:'',rawOpen:true,replace:{from:'',to:nowDate()},sb:{region:'all',cat:'all',src:'all',q:'',from:'',to:nowDate()}};
const $=id=>document.getElementById(id);
function esc(s){const d=document.createElement('div');d.textContent=s||'';return d.innerHTML;}
function safeUrl(u){try{const x=new URL(u);return (x.protocol==='http:'||x.protocol==='https:')?u:'#';}catch(e){return '#';}}
function cleanSum(s){s=s||'';return /comprehensive up-to-date news coverage/i.test(s)?'':s;}
function fmt(s){if(!s)return'';const d=new Date(s);return isNaN(d)?'':d.toLocaleString('zh-HK',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function nowDate(){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
function finalCat(a){return a.final_category||'';}
function hx(c){const n=parseInt(c.slice(1),16);return[n>>16&255,n>>8&255,n&255];}
function mix(c,t,p){const a=hx(c),b2=hx(t);return '#'+a.map((v,i)=>Math.round(v+(b2[i]-v)*p).toString(16).padStart(2,'0')).join('');}
function th(c){return document.body.classList.contains('light')?c:mix(c,'#ffffff',.45);}
function effState(a){if(a.human_action==='approve')return 'accept';if(a.human_action==='reject')return 'reject';return a.decision||'pending_classification';}
function isFinal(a){return effState(a)==='accept';}
function isReview(a){return effState(a)==='review';}
function dState(a){if(a.human_action==='approve')return{l:'人手批准',c:'#0f766e'};if(a.human_action==='reject')return{l:'人手拒絕',c:'#991b1b'};return DECISION[a.decision]||DECISION.pending_classification;}
function groupByEvent(rows){const mp=new Map();rows.forEach(a=>{const k=a.event_key||('solo_'+a.raw_id);if(!mp.has(k))mp.set(k,[]);mp.get(k).push(a);});return [...mp.values()];}
function repOf(g){return g.reduce((b,x)=>((x.summary||'').length>(b.summary||'').length?x:b),g[0]);}

function payloadOf(a){return{digest_id:null,run_date:nowDate(),model:'dual-ai-v8',tab:{global:'tab0',china:'tab1',hongkong:'tab2',taiwan:'tab3'}[a.region]||'tab2',region:a.region==='taiwan'?'tw':a.region,category:a.final_category,tag:'',title:a.title,summary:a.summary||'',orig_title:a.orig_title||a.raw_title||a.title||null,orig_summary:a.orig_summary||a.raw_summary||a.summary||null,ai_take:a.decision_reason||'',impact:'',source:a.source,source_url:safeUrl(a.url),item_date:(a.pub||'').slice(0,10)||nowDate(),industries:[],ai_tools:[],pain_points:[],use_case:[],micro_personas:(a.micro_personas||[]).join('｜'),agent_signal:!!a.agent_signal,automation_level:a.automation_level||0,history_queries:(a.history_queries||[]).join('｜')};}
function inRegion(){return DATA.filter(a=>a.region===S.region&&!a.hidden);}
function pendingClass(){return inRegion().filter(a=>a.decision==='pending_classification'||!a.final_category);}
function pendingEditorial(){return inRegion().filter(a=>a.decision==='pending_editorial'&&a.final_category);}
function classBatch(){return pendingClass().slice(0,BATCH_SIZE);}
function editBatch(){return pendingEditorial().slice(0,BATCH_SIZE);}
function needsAttention(a){return a.decision==='pending_classification'||a.decision==='pending_editorial'||isReview(a);}
function overall(){
const x=inRegion(),pc=pendingClass().length,pe=pendingEditorial().length,classified=x.filter(a=>!!a.final_category).length;
const groups=groupByEvent(x);const evAll=groups.length;let evAcc=0,evRv=0,evRj=0;
groups.forEach(g=>{const st=g.map(effState);if(st.includes('reject'))evRj++;else if(st.includes('review'))evRv++;else if(st.includes('accept'))evAcc++;});
const rv=x.filter(a=>effState(a)==='review').length,ac=x.filter(a=>effState(a)==='accept').length,rj=x.filter(a=>effState(a)==='reject').length,fc=x.filter(isFinal).length;
const evDone=groupByEvent(x.filter(a=>!!a.final_category)).length;
return{total:x.length,classified,pending_classification:pc,pending_editorial:pe,review:rv,accept:ac,reject:rj,final:fc,ready:pc===0&&pe===0&&rv===0,evAll,evDone,evAcc,evRv,evRj,dup:x.length-evAll};}

function paintDashboard(){
const o=overall(),deck=$('flowdeck'),stats=$('dashboardStats');
if($('regionTitle'))$('regionTitle').textContent=REGION_NAME[S.region]||S.region;
if(deck){
const steps=[
{key:'RAW',title:'載入新聞',desc:'匯入原始報道'},
{key:'AI #1',title:'初步分類',desc:'分類及合併事件'},
{key:'AI #2',title:'編輯判讀',desc:'評估實際影響'},
{key:'Overall',title:'全局覆核',desc:'處理待確認項目'},
{key:'Final',title:'確認入庫',desc:'檢查候選內容'},
{key:'已入庫',title:'入庫紀錄',desc:'回看已發布資料'}
];
deck.innerHTML=steps.map((step,i)=>{const n=i+1,active=S.stage===n;return '<button type="button" class="flowitem '+(active?'active':'')+' '+(S.stage>n?'done':'')+'" data-s="'+n+'" aria-current="'+(active?'step':'false')+'" aria-label="第 '+n+' 步：'+step.title+'（'+step.key+'）"><small>0'+n+'</small><span class="flowtitle">'+step.title+'</span><span class="flowkey">'+step.key+'</span><span class="flowdesc">'+step.desc+'</span></button>';}).join('');
deck.querySelectorAll('button[data-s]').forEach(button=>button.onclick=()=>setStage(+button.dataset.s));
}
if(stats){
const ready=o.total>0;
const classNote=ready?'AI #1 已整合 '+o.evDone+' 個事件（尚有 '+(o.total-o.classified)+' 篇未分類）':'等待載入新聞';
const acceptNote=ready?'可入庫 '+o.evAcc+' 個事件':'完成判讀後顯示';
const reviewNote=ready?(o.review?'需要人手確認 '+o.evRv+' 個事件':'暫時沒有待覆核項目'):'需要時交由人手確認';
const rejectNote=ready?(o.reject?'已篩走 '+o.evRj+' 個事件':'暫時沒有不收錄項目'):'完成判讀後顯示';
stats.innerHTML='<div class="stat primary"><label>分類進度</label><strong>'+o.classified+'<span> / '+o.total+'</span></strong><small>'+classNote+'</small></div><div class="stat mint"><label>通過篩選</label><strong>'+o.accept+'</strong><small>'+acceptNote+'</small></div><div class="stat amber"><label>需要覆核</label><strong>'+o.review+'</strong><small>'+reviewNote+'</small></div><div class="stat rose"><label>不予收錄</label><strong>'+o.reject+'</strong><small>'+rejectNote+'</small></div>';
}
}

function norm(d){let arr=Array.isArray(d)?d:null;if(!arr&&d&&typeof d==='object')for(const k in d){if(Array.isArray(d[k])){arr=d[k];break;}}if(!arr)return[];return arr.map((x,i)=>{const a={...x};a.raw_id=x.raw_id||('raw_'+Date.now()+'_'+i);a.title=x.title||'(無標題)';a.summary=cleanSum(x.summary);a.raw_title=x.title||'';a.raw_summary=cleanSum(x.summary);a.orig_title=x.orig_title||'';a.orig_summary=x.orig_summary||'';a.url=x.url||x.link||'#';a.source=x.source_name||x.source||'未知';a.region=x.region||'unknown';a.crawl_hint=x.crawl_hint||x.category||x.cat||x.filter_key||'broad_context';a.final_category=x.final_category||'';a.event_key=x.event_key||'';a.classification_reason=x.classification_reason||x.ai_reason||'';a.decision=x.decision||(a.final_category?'pending_editorial':'pending_classification');a.decision_reason=x.decision_reason||'';a.evidence_status=x.evidence_status||'';a.review_reason=x.review_reason||'';a.human_action=x.human_action||'none';a.hidden=!!x.hidden;a.pub=x.published_at||x.pub||'';a.search_value=x.search_value||'';return a;});}

function load(f){const r=new FileReader();r.onload=e=>{try{DATA=norm(JSON.parse(e.target.result));S.fname=f.name;if($('lastupd'))$('lastupd').textContent=new Date().toLocaleString('zh-HK');setStage(1);}catch(err){alert('JSON 解析失敗：'+err.message);}};r.readAsText(f);}

function stageRows(){const x=inRegion();if(S.stage===5)return x.filter(isFinal);if(S.stage===3)return x.filter(a=>a.decision!=='pending_classification');return x;}
function shown(){let x=stageRows();if(S.cat==='attention')return x.filter(needsAttention);if(S.cat==='review')return x.filter(isReview);if(S.cat==='accept')return x.filter(a=>effState(a)==='accept');if(S.cat==='reject')return x.filter(a=>effState(a)==='reject');if(S.cat==='pending_classification')return x.filter(a=>a.decision==='pending_classification');if(S.cat==='pending_editorial')return x.filter(a=>a.decision==='pending_editorial');if(S.cat==='multi'){const cnt={};x.forEach(a=>{if(a.event_key)cnt[a.event_key]=(cnt[a.event_key]||0)+1;});return x.filter(a=>a.event_key&&cnt[a.event_key]>1);}if(S.cat.startsWith('raw:'))return x.filter(a=>a.crawl_hint===S.cat.slice(4));if(S.cat!=='all')return x.filter(a=>finalCat(a)===S.cat);if(S.group!=='all')return x.filter(a=>GROUPS[S.group].includes(finalCat(a)));return x;}

function b(label,c){const cc=th(c);return '<span class="badge" style="background:'+cc+'22;color:'+cc+';border:1px solid '+cc+'55">'+esc(label)+'</span>';}
function countBy(rows,key){const out={};rows.forEach(a=>{const v=a[key]||'';if(v)out[v]=(out[v]||0)+1;});return out;}
function chip(label,active,attrs,color){const cc=color?th(color):null;return '<button class="catchip '+(active?'active':'')+'" '+attrs+(cc?' style="color:'+cc+';border-color:'+cc+'"':'')+'>'+esc(label)+'</button>';}

function build(keep){
if(S.stage===6){renderSB();status();return;}
$('dash').classList.remove('hidden');if($('sbView'))$('sbView').classList.add('hidden');
if(!keep){S.cat='all';S.group='all';}const rows=stageRows(),rawCounts=countBy(rows,'crawl_hint'),finalCounts=countBy(rows,'final_category');let h=chip('全部 ('+rows.length+')',S.cat==='all'&&S.group==='all','data-g="all"');const rawKeys=Object.keys(rawCounts).sort((a,b)=>rawCounts[b]-rawCounts[a]||a.localeCompare(b));const showRaw=S.stage<=2||S.rawOpen;h+=chip((showRaw?'▾ ':'▸ ')+'來源類別（'+rawKeys.length+' 種／'+rows.length+' 篇）',showRaw,'data-raw-toggle="1"','#64748b');if(showRaw)rawKeys.forEach(k=>{h+=chip('來源：'+k+' ('+rawCounts[k]+')',S.cat==='raw:'+k,'data-c="raw:'+esc(k)+'"','#64748b');});if(Object.keys(finalCounts).length){for(const g in GROUPS){const n=GROUPS[g].reduce((v,c)=>v+(finalCounts[c]||0),0);if(n)h+=chip(g+' ('+n+')',S.group===g&&S.cat==='all','data-g="'+g+'"');}Object.keys(finalCounts).forEach(k=>{h+=chip((FINAL_CATS[k]||k)+' ('+finalCounts[k]+')',S.cat===k,'data-c="'+k+'"',CAT_COLOR[k]||'#64748b');});}const evCounts=countBy(rows,'event_key');let mG=0,mA=0;for(const k in evCounts){if(evCounts[k]>1){mG++;mA+=evCounts[k];}}if(mG)h+=chip('🔗 合併事件 ('+mG+' 組／'+mA+' 篇)',S.cat==='multi','data-c="multi"','#0984e3');if(S.stage===4){const o=overall();h+=chip('所有問題 ('+(o.pending_classification+o.pending_editorial+o.review)+')',S.cat==='attention','data-c="attention"','#ea580c')+chip('AI 接受 ('+o.accept+')',S.cat==='accept','data-c="accept"','#16a34a')+chip('AI 拒絕 ('+o.reject+')',S.cat==='reject','data-c="reject"','#dc2626');if(o.review)h+=chip('待人覆核 ('+o.review+')',S.cat==='review','data-c="review"','#ea580c');}else if(S.stage>=2){const rv=rows.filter(isReview).length;if(rv)h+=chip('待人覆核 ('+rv+')',S.cat==='review','data-c="review"','#ea580c');}$('cats').innerHTML=h;$('cats').querySelectorAll('button').forEach(q=>q.onclick=()=>{if(q.dataset.rawToggle){S.rawOpen=!S.rawOpen;build(true);return;}if(q.dataset.g!==undefined){S.group=q.dataset.g;S.cat='all';}else{S.cat=q.dataset.c;S.group='all';}build(true);});render();status();paintDashboard();}

function status(){const o=overall(),open=o.pending_classification+o.pending_editorial+o.review;let s='';if(S.stage===1)s='RAW · '+(S.fname?esc(S.fname):'未載入')+' · '+o.total+' 篇';if(S.stage===2)s='AI #1 · '+o.classified+'/'+o.total+' 已分類 (Batch: '+BATCH_SIZE+')';if(S.stage===3)s='AI #2 · '+(o.classified-o.pending_editorial)+'/'+o.classified+' 已判讀 (Batch: '+BATCH_SIZE+')';if(S.stage===4)s='Overall · '+o.classified+'/'+o.total+' 分類 · '+open+' 項待處理 · '+o.evAll+' 事件（重複 '+o.dup+' 篇）';if(S.stage===5){const rows=stageRows(),rr=S.replace;s='Final · '+groupByEvent(rows).length+' 個候選事件（'+rows.length+' 篇合併） · 指定日期重入庫：'+(rr.from||'未選開始日')+' 至 '+rr.to+' · 地區：'+(REGION_NAME[S.region]||S.region);}if(S.stage===6)s='⑥ 已入庫 · 目前篩選結果：'+sbShown().length+' 行 · '+sbScopeLabel();$('statusbar').innerHTML=s;}

function render(){const o=overall(),ov=$('overall');if(S.stage===4){const open=o.pending_classification+o.pending_editorial+o.review;ov.classList.remove('hidden');ov.innerHTML='<div class="overall-brief"><strong>Overall</strong>'+b('RAW '+o.total,'#64748b')+b('分類 '+o.classified+'/'+o.total,'#0984e3')+b('接受 '+o.accept,'#16a34a')+b('覆核 '+o.review,'#ea580c')+b('拒絕 '+o.reject,'#dc2626')+b('事件 '+o.evAll,'#0984e3')+b('重複 '+o.dup+' 篇','#64748b')+b('可入庫 '+o.evAcc+' 事件','#16a34a')+'<span class="note">'+(o.ready?'已完成，可入庫。':open+' 項未完成。')+'</span></div>';}else{ov.classList.add('hidden');ov.innerHTML='';}
const rows=shown().sort((a,b2)=>(b2.pub||'').localeCompare(a.pub||''));
const groups=groupByEvent(rows).sort((g1,g2)=>(repOf(g2).pub||'').localeCompare(repOf(g1).pub||''));
$('count').textContent=groups.length+' 個事件 / '+rows.length+' 篇';
const revGroups=groups.filter(g=>g.some(isReview));const revIds=[];revGroups.forEach(g=>g.forEach(a=>revIds.push(a.raw_id)));
const cA=th('#16a34a'),cR=th('#dc2626');
const bulk=revGroups.length?'<div style="margin:0 0 12px;display:flex;gap:8px;flex-wrap:wrap;align-items:center"><span style="font-size:11px;font-weight:700">批量處理待覆核：</span><button data-bulk="approve" style="padding:8px 14px;border-radius:10px;border:1px solid '+cA+';background:'+cA+'11;color:'+cA+';font-weight:700;cursor:pointer">✅ 全部批准入庫（'+revGroups.length+' 事件／'+revIds.length+' 篇）</button><button data-bulk="reject" style="padding:8px 14px;border-radius:10px;border:1px solid '+cR+';background:'+cR+'11;color:'+cR+';font-weight:700;cursor:pointer">⛔ 全部不收錄（'+revGroups.length+' 事件／'+revIds.length+' 篇）</button></div>':'';
$('list').innerHTML=bulk+(groups.map(g=>card(repOf(g),g)).join('')||'<div class="empty">沒有新聞</div>');
$('list').querySelectorAll('[data-bulk]').forEach(q=>q.onclick=()=>{const act=q.dataset.bulk==='approve'?'approve':'reject';if(!confirm('確定將目前顯示嘅 '+revGroups.length+' 個待覆核事件（'+revIds.length+' 篇）全部'+(act==='approve'?'批准入庫':'不收錄')+'？人手決定會覆蓋 AI 決定。'))return;revIds.forEach(id=>{const a=DATA.find(x=>x.raw_id===id);if(a)a.human_action=act;});build(true);});
$('list').querySelectorAll('[data-act]').forEach(q=>q.onclick=()=>{const ids=(q.dataset.gids||'').split('|');const act=q.dataset.act==='approve'?'approve':'reject';ids.forEach(id=>{const a=DATA.find(x=>x.raw_id===id);if(a)a.human_action=act;});build(true);});
$('list').querySelectorAll('[data-split]').forEach(q=>q.onclick=()=>{const a=DATA.find(x=>x.raw_id===q.dataset.split);if(a){a.event_key='solo_'+a.raw_id;build(true);}});}

function card(a,g){
g=g||[a];
const cat=finalCat(a),dc=dState(a),
finalBadge=cat?b(FINAL_CATS[cat]||cat,CAT_COLOR[cat]||'#64748b'):b('待分類','#64748b'),
reason1=a.classification_reason?'<div class="ai-reason" style="border-left-color:var(--cyan);background:rgba(93,224,255,.07)"><span style="color:var(--cyan)">AI #1 </span>'+esc(a.classification_reason)+'</div>':'',
reason=a.decision_reason?'<div class="ai-reason"><span>AI #2 </span>'+esc(a.decision_reason)+'</div>':'',
v5meta=((a.micro_personas||[]).length||(a.history_queries||[]).length||a.agent_signal)?'<div class="ai-reason" style="border-left-color:var(--violet);background:rgba(143,124,255,.07)"><span style="color:var(--violet)">v5 </span>'+((a.micro_personas||[]).length?('🎯 '+esc(a.micro_personas.join('；'))):'')+(a.agent_signal?(' ｜ 🦾 手腳 L'+(a.automation_level||0)):'')+((a.history_queries||[]).length?(' ｜ 🔍 '+esc(a.history_queries.join('；'))):'')+'</div>':'',
gids=g.map(x=>x.raw_id).join('|'),
manual=isReview(a)?'<div class="reviewline">需人手確認（成組事件）。<div class="review-actions"><button class="approve" data-act="approve" data-gids="'+gids+'">批准入庫</button><button class="reject" data-act="reject" data-gids="'+gids+'">不收錄</button></div></div>':'',
ev=(g.length>1)?'<details class="evgroup" style="margin-top:8px"><summary style="cursor:pointer;font-size:11px;font-weight:700">🔗 同一事件・'+g.length+' 個來源</summary><div style="margin-top:6px;font-size:11px;opacity:.75">'+g.map(x=>'<div style="margin:2px 0">・'+esc(x.source)+'：<a href="'+esc(safeUrl(x.url))+'" target="_blank" rel="noopener noreferrer">'+esc(x.title)+'</a> <button data-split="'+esc(x.raw_id)+'" style="margin-left:6px;font-size:10px;cursor:pointer;border:1px solid var(--line);border-radius:6px;background:transparent;color:var(--muted)">拆出</button></div>').join('')+'</div></details>':'',
pv=S.stage===5?'<details class="payload" style="margin-top:8px"><summary style="cursor:pointer;font-size:11px;font-weight:700">📦 入庫預覽・以下就係會 INSERT 嘅全部欄位</summary><div style="margin-top:6px;font-size:10.5px;opacity:.85">'+Object.entries(payloadOf(a)).map(([k,v])=>'<div style="margin:2px 0"><b>'+esc(k)+'</b>：'+(v===null?'<i>null</i>'+(k.indexOf('orig')===0?'（本地廣東話，唔存原文）':''):(Array.isArray(v)?'<i>[]</i>':esc(String(v))))+'</div>').join('')+'</div></details>':'';
return '<div class="card"><h3><a href="'+esc(safeUrl(a.url))+'" target="_blank" rel="noopener noreferrer">'+esc(a.title)+'</a></h3><div class="meta">'+finalBadge+b(dc.l,dc.c)+'<span>'+esc(a.source)+'</span>'+(a.pub?'<span>'+fmt(a.pub)+'</span>':'')+'</div>'+(a.summary?'<div class="sum">'+esc(a.summary.slice(0,180))+'</div>':'')+reason1+reason+v5meta+ev+pv+manual+'</div>';
}

const AI1_STATIC='你是 AI #1：香港 AI 情報入庫前處理專員。你的唯一任務只有三項：1. 理解每篇新聞的 Title + Summary。2. 為每篇新聞選擇唯一一個 final_category。3. 判斷哪些新聞屬於同一個具體事件，並建立 event_key。你不是編輯，不是審稿人，不是翻譯員。\n# 一、絕對角色邊界\n你只做分類與事件合併。嚴禁：翻譯原文；改寫原文；摘要原文；補充原文沒有提供的事實；判斷新聞是否重要；判斷是否值得香港人閱讀；判斷 accept/review/reject；判斷是否應入庫；判斷新聞真偽（除非新聞本身明確描述安全、詐騙、深偽、漏洞或信任事件，而該內容本身屬於 safety_trust）；因為新聞來自某家公司就自動歸入該公司的泛化 event_key；因為多篇新聞講同一家公司就自動合併；因為多篇新聞在同一天發布就自動合併；因為多篇新聞同屬 AI 就建立 ai_news_xxx 等空泛 key；因為是 roundup/digest/morning briefing/weekly roundup 就把其中所有故事合併成一個事件。原文語言完全不重要。不要識別語言，不要翻譯，不要改寫 Title 或 Summary。\n# 二、輸入與輸出對應\n輸入是一批新聞，每篇都有唯一 i。你必須保留每篇輸入新聞的 i；每個 i 必須出現一次且只可以出現一次；不可新增、刪除、跳過、重複、重新排序 i；最終必須輸出恰好 N 個 objects（N＝輸入新聞數量）。即使新聞非常多，也必須逐篇處理。不可因為批次很長而省略、合併輸出、只處理部分新聞或提前停止。\n# 三、FINAL_CATEGORY：唯一分類規則（Priority Cascade，由上至下，第一個明確符合的類別立即鎖定，STOP CLASSIFYING，不得再用後面的類別重新分類）\nP1 safety_trust：AI 安全漏洞、模型或 AI 系統被攻擊、深偽、AI 詐騙、AI 生成假資訊、私隱／個人資料洩漏、AI 安全事故、trust/safety 爭議、模型安全風險、AI 系統遭濫用。即使同一事件同時涉及政府、產品或企業，也優先 safety_trust。\nP2 regulation_public：政府政策、法例、法規、監管措施、官方 AI 指引、版權政策、政府 AI 採購／公共服務、公共部門 AI 政策、官方禁令／限制、AI 合規要求。即使內容涉及某家公司產品或價格，只要核心動作是政府／監管措施，就歸 regulation_public。\nP3 price_free：AI 產品降價、API 降價、免費額度增加、收費模式改變、免費開放、訂閱價格改變、token pricing 改變、credits/quota 改變、價格戰。即使產品本身屬於新工具，只要核心是價格或免費政策改變，優先 price_free。\nP4 tools_access：新工具、新模型、新產品、新功能正式發布、開放或可供使用者開始使用。判斷重點：「現在有甚麼新東西可以用？」如果只是介紹工具原理、性能或技術架構而沒有「新發布／新開放」核心事件，不要用 tools_access。\nP5 real_use：真實企業使用案例、真實行業落地、實測、field test、deployment result、productivity result、ROI/cost saving result、實際工作流程應用、真實客戶使用成效。重點：「AI 已經怎樣被實際使用？」廠商單方面宣稱不等於真實落地；產品宣傳不能因出現 case study 字眼就自動歸入 real_use。\nP6 work_sme：工作模式改變、就業、職位、HR、招聘、AI 對企業策略的影響、SME、創業、行業結構、產業鏈、生產力趨勢、企業採用 AI 的策略、AI 對某個行業的結構性影響。純股價、估值、股票升跌，不因為涉及 AI 公司而自動歸入此類。\nP7 learning_family：教育、學校、學生、教師、親子、家庭、長者、個人日常生活、學習方法、家庭使用 AI。\nP8 tech_background：只有 P1–P7 都不成立時才使用：純技術原理、模型架構、演算法、benchmark、純跑分、training technique、research paper、技術背景、模型能力分析。\n# 四、分類 Tie-breaker\nSafety > Regulation > Price > New Access > Real Use > Work/SME > Learning/Family > Technical Background。核心原則：分類的是「新聞正在報道的核心事件」，不是文章提及最多的名詞。\n# 五、EVENT_KEY：事件級，而不是公司級\n格式 lowercase_snake_case，由「核心實體＋核心動作／事件」組成（例：openai_gpt4o_launch、anthropic_claude_api_price_cut）。禁止：ai_news、ai_news_0819、openai_news、microsoft_news、latest_ai、ai_update、technology_news。公司名稱不是事件。\n# 六、同一事件：必須合併\n同一核心實體＋同一核心動作＋同一核心產品／政策／發布；不同媒體／不同語言報道同一件事；不同標題但事實核心一致；同一新聞週期內的正常跟進報道 → 相同 event_key。\n# 七、超過一星期：視為新事件\n同一產品／公司但核心動作已經是新的，而且與原事件相隔超過約一星期 → 新 event_key。不要因為產品名稱相同就把所有後續新聞塞入原 event_key。\n# 八、Roundup 特殊規則\nroundup/digest/morning briefing/多事件合集 → 整篇文章必須建立自己的獨立 event_key（例：ai_roundup_20260819），禁止把裡面不同故事強行合併，更禁止因提及某公司就歸入該公司 key。\n# 九、同公司不同產品／不同動作：禁止合併\n同一公司兩個不同產品、不同模型、不同 API 更新、今日 launch 下星期降價、launch 與企業合作、不同監管事件 → 不同 event_key。\n# 十、資訊不足時不要幻想\n不得自行補充日期、猜測版本、猜測產品、補充新聞沒有提供的動作；但仍然必須建立最具體、且有證據支持的事件級 key。寧願 anthropic_model_launch，也不要幻想成 anthropic_claude_5_launch。\n# 十一、REASON\n使用自然港式廣東話；20 字內；只解釋「點解屬於呢個 category」；不可重新摘要新聞；不可加入新聞沒有提供的新事實；不可寫重要性判斷；不可寫 accept/reject；不可翻譯原文。\n# 十二、最終輸出格式\n只可以輸出 JSON array。不可輸出 Markdown、```json、解釋、開場白、結尾、註解、任何額外文字。每個 object 只可以有四個欄位：i、final_category、event_key、reason。不可新增、刪除或改名任何欄位。\n# 十三、輸出前內部強制檢查\n1 是否處理所有輸入新聞？2 輸出 object 數量是否＝N？3 每個 i 是否出現一次？4 是否有跳 i？5 是否有重複 i？6 是否保持輸入 i 順序？7 每個 category 是否遵守 Priority Cascade？8 是否把 Price 錯分為 Tools？9 是否把新工具錯分為 Real Use？10 是否把 roundup 錯誤合併？11 是否把不同產品／不同動作錯誤合併？12 event_key 是否具體到事件？13 是否出現空泛 company-level key？14 是否自行幻想 Title/Summary 沒有提供的資訊？15 reason 是否 ≤20 字？16 是否沒有任何翻譯或改寫原文行為？17 是否沒有 accept/review/reject 判斷？如果任何一項不符合，必須在輸出前自行修正。最重要：寧願分類保守，也不能跳過任何新聞；寧願兩篇獨立事件各自建立 key，也不要把不同事件錯誤合併。最終只輸出 JSON array。\n\n';

