```javascript
/* ================= v13.2 執尾：☁️ 確認彈窗顯示真實 per-item 模型、刪爬蟲版本行 ================= */
(function(){
if(!window._oneBtn)return;
window._oneBtn.onclick=async function(){
  if(!overall().ready)return alert('⛔ 請先完成 ④ Overall 總覽內所有待分類、待 AI #2 決定及 Review 項目。');
  var scope=selectedReplaceScope();if(!scope)return alert('請先選擇入庫日期範圍。');
  var c=cfg();if(!c.url||!c.key)return alert('先撳 Supabase 填 URL＋anon key');
  var rows=finalInsertRows(scope).rows;
  if(!rows.length)return alert('目前 '+replaceScopeLabel(scope)+' 內沒有可入庫的接受事件。');
  var u=c.url.replace(/\/+$/,'');var oldCount=0;
  try{oldCount=await countReplaceScope(u,c,scope);}catch(e){return alert('❌ 未能取得舊記錄數量，已取消操作：'+e.message);}
  var m1={},m2={};
  rows.forEach(function(r){if(r.ai1_model)m1[r.ai1_model]=1;if(r.ai2_model)m2[r.ai2_model]=1;});
  var s1=Object.keys(m1).join('／')||'（無）';
  var s2=Object.keys(m2).join('／')||'（無）';
  if(!confirm('☁️ 入庫確認\n\n範圍：'+replaceScopeLabel(scope)+'\n刪除舊記錄：'+oldCount+' 行\n插入新事件：'+rows.length+' 個\n\nai1_model：'+s1+'\nai2_model：'+s2+'\n\n確定＝執行；取消＝唔郁。'))return;
  try{
    if(oldCount>0){var d=await fetch(u+'/rest/v1/ainews_items_final?'+replaceScopeQuery(scope),{method:'DELETE',headers:{apikey:c.key,Authorization:'Bearer '+c.key,Prefer:'return=minimal'}});if(!d.ok)throw new Error('刪除失敗：HTTP '+d.status+' '+await d.text());}
    await insertRows(u,c,rows);
    alert('✅ 已入庫 '+rows.length+' 個事件（刪除舊 '+oldCount+' 行）。');
  }catch(e){alert('❌ 入庫未完成：'+e.message+'。如刪除已成功但新增失敗，請勿重複操作，先到⑥已入庫核對。');}
};
})();
```

