收到，⑥ 嘅 🤖 模型移去最前（AI #1 行同 AI TAKE 行都係）。以下 **v13.3** 貼喺 `.js` 最最尾，儲存＋Refresh：

```javascript
/* ================= v13.3 ⑥ 顯示：🤖 模型放最前 ================= */
(function(){
renderSB=function(){
$('dash').classList.add('hidden');
var sbView=$('sbView');
if(!sbView){sbView=document.createElement('div');sbView.id='sbView';$('dash').parentNode.insertBefore(sbView,$('dash'));}
sbView.classList.remove('hidden');
var srcCounts={};SB.forEach(function(r){if(r.source)srcCounts[r.source]=(srcCounts[r.source]||0)+1;});
var srcKeys=Object.keys(srcCounts).sort(function(a,b){return srcCounts[b]-srcCounts[a]||a.localeCompare(b);});
var fHtml='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;align-items:center">';
fHtml+='<select id="sbFRegion" style="padding:6px;border-radius:6px;background:var(--surface);color:var(--text);border:1px solid var(--line)"><option value="all">全部地區</option>'+Object.entries(SB_REGION).map(function(e){return '<option value="'+e[0]+'" '+(S.sb.region===e[0]?'selected':'')+'>'+e[1]+'</option>';}).join('')+'</select>';
fHtml+='<select id="sbFCat" style="padding:6px;border-radius:6px;background:var(--surface);color:var(--text);border:1px solid var(--line)"><option value="all">全部分類</option>'+Object.entries(FINAL_CATS).map(function(e){return '<option value="'+e[0]+'" '+(S.sb.cat===e[0]?'selected':'')+'>'+e[1]+'</option>';}).join('')+'</select>';
fHtml+='<select id="sbFSrc" style="padding:6px;border-radius:6px;background:var(--surface);color:var(--text);border:1px solid var(--line)"><option value="all">全部來源 ('+srcKeys.length+')</option>'+srcKeys.map(function(k){return '<option value="'+esc(k)+'" '+(S.sb.src===k?'selected':'')+'>'+esc(k)+' ('+srcCounts[k]+')</option>';}).join('')+'</select>';
fHtml+='<input type="date" id="sbFFrom" value="'+S.sb.from+'" style="padding:6px;border-radius:6px;background:var(--surface);color:var(--text);border:1px solid var(--line)">';
fHtml+='<input type="date" id="sbFTo" value="'+S.sb.to+'" style="padding:6px;border-radius:6px;background:var(--surface);color:var(--text);border:1px solid var(--line)">';
fHtml+='<input type="text" id="sbFQ" placeholder="關鍵字..." value="'+esc(S.sb.q)+'" style="padding:6px;border-radius:6px;background:var(--surface);color:var(--text);border:1px solid var(--line);width:150px">';
fHtml+='<button id="sbFReset" style="padding:6px 10px;border-radius:6px;border:1px solid var(--line);background:var(--surface);color:var(--muted)">Reset</button>';
fHtml+='</div>';
var rows=sbShown(),scope=sbScopeLabel();
var scopeHtml='<div id="sbScope" style="display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:0 0 12px;padding:11px 13px;border:1px solid var(--line);border-left:4px solid var(--cyan);border-radius:12px;background:linear-gradient(90deg,rgba(29,112,162,.12),rgba(27,50,119,.04));color:var(--muted);font-size:13px"><strong style="color:var(--text);font-size:14px">已入庫記錄</strong><span>根據 '+esc(scope)+'</span></div>';
var listHtml='<div style="font-size:12px;color:var(--muted);margin-bottom:10px">目前篩選結果：<b style="color:var(--text)">'+rows.length+'</b> 行</div>';
listHtml+=rows.map(function(r){
var catColor=CAT_COLOR[r.category]||'#64748b';
var hasV5=(r.micro_personas||r.history_queries||r.agent_signal===true);
var h='<div class="card" style="margin-bottom:10px"><h3 style="font-size:14px;margin:0 0 8px"><a href="'+esc(safeUrl(r.source_url))+'" target="_blank" rel="noopener noreferrer">'+esc(r.title)+'</a></h3>';
h+='<div class="meta" style="font-size:10px;color:var(--muted);display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px">'+b(SB_REGION[r.region]||r.region,'#64748b')+b(FINAL_CATS[r.category]||r.category,catColor)+'<span>'+esc(r.source)+'</span><span>item: '+esc(r.item_date)+'</span><span>run: '+esc(r.run_date||'')+'</span><span>model: '+esc(r.model)+'</span></div>';
if(r.summary)h+='<div class="sum" style="font-size:12px;color:var(--muted);margin-bottom:8px">'+esc(r.summary.slice(0,180))+'</div>';
if(r.ai1_reason||r.ai1_model)h+='<div class="ai-reason" style="margin-top:8px;padding:8px 10px;border-left:2px solid var(--cyan);border-radius:0 8px 8px 0;background:rgba(93,224,255,.07);color:var(--text);font-size:11px;line-height:1.5"><span style="color:var(--cyan);font-size:10px;font-weight:700;letter-spacing:.08em;margin-right:8px">AI #1</span>'+(r.ai1_model?('🤖 ai1_model: '+esc(r.ai1_model)+' ｜ '):'')+esc(r.ai1_reason||'')+'</div>';
if(r.ai_take)h+='<div class="ai-reason" style="margin-top:6px;padding:8px 10px;border-left:2px solid var(--violet);border-radius:0 8px 8px 0;background:rgba(143,124,255,.08);color:var(--text);font-size:11px;line-height:1.5"><span style="color:var(--violet);font-size:10px;font-weight:700;letter-spacing:.08em;margin-right:8px">AI TAKE</span>'+(r.ai2_model?('🤖 ai2_model: '+esc(r.ai2_model)+' ｜ '):'')+esc(r.ai_take)+'</div>';
if(hasV5)h+='<div class="ai-reason" style="margin-top:6px;padding:8px 10px;border-left:2px solid var(--violet);border-radius:0 8px 8px 0;background:rgba(143,124,255,.08);color:var(--text);font-size:11px;line-height:1.5"><span style="color:var(--violet);font-size:10px;font-weight:700;letter-spacing:.08em;margin-right:8px">v5</span>'+(r.micro_personas?('🎯 '+esc(r.micro_personas)):'')+(r.agent_signal===true?(' ｜ 🦾 手腳 L'+(r.automation_level||0)):'')+(r.history_queries?(' ｜ 🔍 '+esc(r.history_queries)):'')+'</div>';
h+='<details style="margin-top:8px"><summary style="cursor:pointer;font-size:10px;font-weight:700;color:var(--muted)">📄 全部欄位（'+Object.keys(r).length+' 列）・包括原文核對</summary><div style="margin-top:6px;font-size:10.5px;opacity:.85">'+Object.entries(r).map(function(e){return '<div style="margin:2px 0"><b>'+esc(e[0])+'</b>：'+(e[1]===null||e[1]===undefined?'<i>null</i>':(Array.isArray(e[1])?esc(JSON.stringify(e[1])):esc(String(e[1]))))+'</div>';}).join('')+'</div></details>';
h+='</div>';
return h;
}).join('');
sbView.innerHTML=scopeHtml+fHtml+'<div id="sbList">'+listHtml+'</div>';
$('sbFRegion').onchange=function(e){S.sb.region=e.target.value;refreshSB();};
$('sbFCat').onchange=function(e){S.sb.cat=e.target.value;refreshSB();};
$('sbFSrc').onchange=function(e){S.sb.src=e.target.value;refreshSB();};
$('sbFFrom').onchange=function(e){S.sb.from=e.target.value;refreshSB();};
$('sbFTo').onchange=function(e){S.sb.to=e.target.value;refreshSB();};
$('sbFQ').oninput=function(e){S.sb.q=e.target.value;refreshSB();};
$('sbFReset').onclick=function(){S.sb={region:'all',cat:'all',src:'all',q:'',from:'',to:nowDate()};refreshSB();};
};
})();
```

